package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="generation_jobs") public class GenerationJob { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="blueprint_id") private UUID blueprintId; @Column(nullable=false,length=30) private String status="QUEUED"; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public void setProjectId(UUID v){projectId=v;} public UUID getBlueprintId(){return blueprintId;} public void setBlueprintId(UUID v){blueprintId=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getCreatedAt(){return createdAt;} }
